#include <iomanip>
#include <iostream>

int main() {
    const int sum = 85 + 90 + 78;
    std::cout << sum / 3 << '\n';

    const double average = static_cast<double>(sum) / 3;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << average << '\n';
    std::cout << static_cast<int>(average) << '\n';

    const double f = 98.6;
    std::cout << std::setprecision(1);
    std::cout << 5 / 9 * (f - 32) << '\n';  // 5 / 9 is 0 first
    std::cout << (f - 32) * 5 / 9 << '\n';  // double from the start
    return 0;
}

