#include <iomanip>
#include <iostream>

int main() {
    const int sum = 21 + 19 + 24 + 23;
    const double km = 5.0;
    const double MILES_PER_KM = 0.621371;
    std::cout << std::fixed << std::setprecision(2);

    std::cout << sum / 4 << '\n';
    std::cout << static_cast<double>(sum) / 4 << '\n';

    std::cout << 45 / 60 * 100 << '\n';
    std::cout << 45 * 100 / 60 << '\n';

    const double miles = km * MILES_PER_KM;
    std::cout << miles << '\n';
    std::cout << static_cast<int>(miles) << '\n';

    return 0;
}

