#include <iostream>

int main() {
    int score = 0;
    int moves = 0;

    score += 40;
    ++moves;
    std::cout << "add " << score << '\n';
    score *= 3;
    ++moves;
    std::cout << "triple " << score << '\n';
    score -= 25;
    ++moves;
    std::cout << "lose " << score << '\n';
    score /= 2;
    ++moves;
    std::cout << "halve " << score << '\n';
    score %= 7;
    ++moves;
    std::cout << "remainder " << score << '\n';
    std::cout << "moves " << moves << '\n';

    const int before = moves++;
    std::cout << before << ' ' << moves << '\n';

    return 0;
}
